    () =>
      Effect.gen(function* () {
        const times = Array.from(
          { length: SHUFFLED },
          (_, i) => ((i * 37) % SHUFFLED) * (4 / SHUFFLED),
        );
        const between = [...HISTORY_A, ...HISTORY_B];
